    function decide_wing_position(){
        //네비게이션바 위치 + 네비게이션바 높이 50 + (index면 메인화면 슬라이드) - 상단팝업 높이
        wing_up = nav_category_area_height+main_slide_height-jQuery('.bn_top').height();
        wing_down = layout_footer_height-155;
        scroll = jQuery(window).scrollTop();
        if( jQuery(window).scrollTop() < wing_up ){
            scroll = wing_up;
        }else if( jQuery(window).scrollTop() > wing_down ){
            scroll = wing_down
        }
    }
